module pll(input clk, input reset, input signal_in, output reg signal_out);  
    reg [3:0] phase;  
    reg [3:0] error;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            phase <= 0;  
            signal_out <= 0;  
        end else begin  
            // Phase detection logic  
            error <= signal_in ^ phase;  
            // Adjust phase based on error  
            if (error)  
                phase <= phase + 1;  
            signal_out <= phase[3]; // Example output based on the most significant bit of phase  
        end  
    end  
endmodule

