module pitch_detector(  
    input clk,  
    input reset,  
    input [15:0] audio_sample,  
    output reg [6:0] detected_pitch  
);  

reg [15:0] previous_sample;  
reg [6:0] count;  

always @(posedge clk or posedge reset) begin  
    if (reset) begin  
        previous_sample <= 0;  
        count <= 0;  
        detected_pitch <= 0;  
    end else begin  
        if ((previous_sample[15] == 0 && audio_sample[15] == 1) || (previous_sample[15] == 1 && audio_sample[15] == 0)) begin  
            count <= count + 1;  
        end  
        previous_sample <= audio_sample;  
        if (count >= 128) begin  
            detected_pitch <= count[6:0];  
            count <= 0;  
        end  
    end  
end  
endmodule

