module uart_transmitter #(parameter BAUD_RATE = 9600, parameter CLOCK_FREQ = 50000000) (  
    input wire clk,  
    input wire rst,  
    input wire [7:0] data_in,  
    input wire tx_en,  
    output reg tx,  
    output reg busy  
);  

    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;  
    localparam START_BIT = 1'b0;  
    localparam STOP_BIT = 1'b1;  

    reg [3:0] bit_index;  
    reg [15:0] counter;  
    reg [10:0] shift_reg;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            tx <= 1;  
            busy <= 0;  
            bit_index <= 0;  
            counter <= 0;  
            shift_reg <= 0;  
        end else begin  
            if (tx_en && !busy) begin  
                busy <= 1;  
                shift_reg <= {STOP_BIT, data_in, START_BIT};  
                bit_index <= 0;  
                counter <= 0;  
            end else if (busy) begin  
                if (counter < BIT_PERIOD - 1) begin  
                    counter <= counter + 1;  
                end else begin  
                    counter <= 0;  
                    if (bit_index < 10) begin  
                        tx <= shift_reg[bit_index];  
                        bit_index <= bit_index + 1;  
                    end else begin  
                        busy <= 0;  
                        tx <= 1;  
                    end  
                end  
            end  
        end  
    end  
endmodule

