module chebyshev_filter (
    input clk,
    input reset,
    input [7:0] x_in,
    output reg [7:0] y_out
);
    // Filter coefficients (example values)
    parameter [7:0] b0 = 8'd1;
    parameter [7:0] b1 = 8'd2;
    parameter [7:0] b2 = 8'd1;
    parameter [7:0] a1 = 8'd3;
    parameter [7:0] a2 = 8'd1;

    reg [7:0] x_reg [0:2]; // Input buffer (x[n], x[n-1], x[n-2])
    reg [7:0] y_reg [0:2]; // Output buffer (y[n-1], y[n-2])

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y_out <= 8'd0;
            x_reg[0] <= 8'd0;
            x_reg[1] <= 8'd0;
            x_reg[2] <= 8'd0;
            y_reg[0] <= 8'd0;
            y_reg[1] <= 8'd0;
        end else begin
            // Shift input values
            x_reg[2] <= x_reg[1];
            x_reg[1] <= x_reg[0];
            x_reg[0] <= x_in;

            // Calculate output using filter equation
            y_out <= b0 * x_reg[0] + b1 * x_reg[1] + b2 * x_reg[2] 
                     - a1 * y_reg[0] - a2 * y_reg[1];

            // Shift output values
            y_reg[1] <= y_reg[0];
            y_reg[0] <= y_out;
        end
    end
endmodule

