module serializer (
    input clk,
    input reset,
    input [31:0] parallel_in,
    output reg serial_out
);
    reg [4:0] count; // 5 bits to count from 0 to 31

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            serial_out <= 0;
        end else begin
            if (count < 32) begin
                serial_out <= parallel_in[count];
                count <= count + 1;
            end
        end
    end
endmodule

