module rle_encoder (
    input clk,
    input reset,
    input data_in,
    output reg [3:0] run_length,
    output reg encoded_bit,
    output reg valid
);
    reg [3:0] count;
    reg current_bit;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            run_length <= 0;
            encoded_bit <= 0;
            valid <= 0;
            current_bit <= 0;
        end else begin
            if (data_in == current_bit) begin
                if (count < 15) begin
                    count <= count + 1;
                end
            end else begin
                if (count > 0) begin
                    run_length <= count;
                    encoded_bit <= current_bit;
                    valid <= 1;
                    count <= 1; // Reset count for new bit
                    current_bit <= data_in;
                end else begin
                    current_bit <= data_in;
                    count <= 1;
                end
            end
        end
    end
endmodule

