module fractional_n_pll #(parameter N = 4, M = 3) (  
    input clk,  
    input reset,  
    input [7:0] freq_divider,  
    output reg pll_out  
);  
    reg [7:0] counter;  
    reg [7:0] feedback;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            pll_out <= 0;  
        end else begin  
            counter <= counter + 1;  
            if (counter >= freq_divider) begin  
                pll_out <= ~pll_out;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

