module stop_and_wait (
    input clk,
    input rst,
    input ack,
    output reg [1:0] packet,
    output reg send
);
    parameter IDLE = 2'b00, SEND = 2'b01, WAIT_ACK = 2'b10, TIMEOUT = 2'b11;
    reg [1:0] state, next_state;
    reg [3:0] timer;

    initial begin
        state = IDLE;
        packet = 2'b00;
        send = 0;
        timer = 0;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            packet <= 2'b00;
            send <= 0;
            timer <= 0;
        end else begin
            state <= next_state;
            if (state == SEND)
                timer <= timer + 1;
            else
                timer <= 0;
        end
    end

    always @(*) begin
        case (state)
            IDLE: begin
                if (packet < 2'b11) begin
                    next_state = SEND;
                    send = 1;
                end else begin
                    next_state = IDLE;
                    send = 0;
                end
            end
            SEND: begin
                next_state = WAIT_ACK;
                send = 0;
            end
            WAIT_ACK: begin
                if (ack) begin
                    packet = packet + 1;
                    next_state = IDLE;
                end else if (timer < 4'd10) begin
                    next_state = WAIT_ACK;
                end else begin
                    next_state = SEND; // Timeout, resend
                end
            end
            default: begin
                next_state = IDLE;
                send = 0;
            end
        endcase
    end
endmodule

