module butterworth_filter (
    input [4:0] x,       // 5-bit input signal
    input clk,
    input rst,
    output reg [4:0] y   // 5-bit output signal
);

    reg [4:0] y1, y2;    // Previous outputs for the filter

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 5'b00000;
            y1 <= 5'b00000;
            y2 <= 5'b00000;
        end else begin
            // Implementing a simple second-order Butterworth filter
            y <= (x + y1 + y2) / 3; // Simple averaging as an example
            y2 <= y1;
            y1 <= y;
        end
    end
endmodule

