module pll_8x (
    input wire clk_in,
    input wire rst,
    output reg clk_out,
    output reg locked
);
    reg [2:0] counter;
    reg clk_div;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            counter <= 3'b000;
            clk_div <= 1'b0;
            locked <= 1'b0;
        end else begin
            counter <= counter + 1;
            if (counter == 3'b111) begin // 8 cycles to toggle clk_div
                clk_div <= ~clk_div;
                counter <= 3'b000;
            end
            clk_out <= clk_div;
            if (clk_div) locked <= 1'b1; // Indicate PLL is locked
        end
    end
endmodule

