module pitch_detector (
    input clk,
    input reset,
    input [11:0] sample,  // 12-bit input audio sample
    output reg detected     // output high if target pitch is detected
);
    parameter TARGET_PITCH = 12'd2048; // example target pitch level
    parameter THRESHOLD = 12'd100; // threshold for pitch detection

    reg [11:0] previous_sample;
    reg state; // 0: no pitch detected, 1: pitch detected

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            detected <= 0;
            previous_sample <= 0;
            state <= 0;
        end else begin
            if (sample > (TARGET_PITCH - THRESHOLD) && sample < (TARGET_PITCH + THRESHOLD)) begin
                state <= 1; // pitch detected
            end else begin
                state <= 0; // no pitch detected
            end
            detected <= state;
            previous_sample <= sample;
        end
    end
endmodule

