module pulse_generator(
    input wire clk,
    input wire rst,
    input wire [3:0] pulse_width,
    output reg pulse_out
);
    reg [3:0] count;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 0;
            pulse_out <= 0;
        end else if (count > 0) begin
            count <= count - 1;
            pulse_out <= 1;
        end else if (pulse_width > 0) begin
            count <= pulse_width - 1;
            pulse_out <= 1;
        end else begin
            pulse_out <= 0;
        end
    end
endmodule

