module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    output reg timeout  
);  
    parameter TIMEOUT_COUNT = 8'd100;  
    reg [7:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 8'b0;  
            timeout <= 1'b0;  
        end else if (enable) begin  
            if (counter < TIMEOUT_COUNT)  
                counter <= counter + 1;  
            else  
                timeout <= 1'b1;  
        end  
    end  
endmodule

