module iir_filter (
    input clk,
    input rst,
    input signed [15:0] x,      // input signal
    output reg signed [15:0] y   // output signal
);
    reg signed [15:0] a [0:3];   // feedback coefficients
    reg signed [15:0] b [0:3];   // feedforward coefficients
    reg signed [15:0] x_reg [0:3]; // input history
    reg signed [15:0] y_reg [0:3]; // output history

    parameter signed [15:0] a0 = 16'h1A2B; // Coefficients can be adjusted
    parameter signed [15:0] a1 = 16'h1C2D;
    parameter signed [15:0] a2 = 16'h1E2F;
    parameter signed [15:0] a3 = 16'h2021;
    parameter signed [15:0] b0 = 16'h0A0B;
    parameter signed [15:0] b1 = 16'h0C0D;
    parameter signed [15:0] b2 = 16'h0E0F;
    parameter signed [15:0] b3 = 16'h1011;

    initial begin
        a[0] = a0; a[1] = a1; a[2] = a2; a[3] = a3;
        b[0] = b0; b[1] = b1; b[2] = b2; b[3] = b3;
        y = 16'h0;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'h0;
            x_reg[0] <= 16'h0;
            x_reg[1] <= 16'h0;
            x_reg[2] <= 16'h0;
            x_reg[3] <= 16'h0;
            y_reg[0] <= 16'h0;
            y_reg[1] <= 16'h0;
            y_reg[2] <= 16'h0;
            y_reg[3] <= 16'h0;
        end else begin
            // Shift previous input and output values
            x_reg[3] <= x_reg[2];
            x_reg[2] <= x_reg[1];
            x_reg[1] <= x_reg[0];
            x_reg[0] <= x;

            y_reg[3] <= y_reg[2];
            y_reg[2] <= y_reg[1];
            y_reg[1] <= y_reg[0];
            y_reg[0] <= y;

            // Calculate output based on IIR filter equation
            y <= b[0] * x_reg[0] + b[1] * x_reg[1] + b[2] * x_reg[2] + b[3] * x_reg[3]
                - a[1] * y_reg[1] - a[2] * y_reg[2] - a[3] * y_reg[3];
        end
    end
endmodule

