module dma_controller (  
    input clk,  
    input rst,  
    input [1:0] channel_sel, // 2 channels  
    input rw, // read/write signal (1 for read, 0 for write)  
    input [7:0] data_in,  
    output reg [7:0] data_out,  
    output reg transfer_done // status signal for transfer completion  
);  
    reg [1:0] state;  
    reg [1:0] next_state;  
    localparam IDLE = 2'b00,  
               TRANSFER = 2'b01,  
               DONE = 2'b10;  

    always @(posedge clk or posedge rst) begin  
        if (rst)  
            state <= IDLE;  
        else  
            state <= next_state;  
    end  

    always @(*) begin  
        case (state)  
            IDLE: begin  
                transfer_done = 0;  
                if (channel_sel != 2'b00)  
                    next_state = TRANSFER;  
                else  
                    next_state = IDLE;  
            end  
            TRANSFER: begin  
                if (rw) // read operation  
                    data_out = /* read from memory */ data_in;  
                else // write operation  
                    /* write data_in to memory */;  
                next_state = DONE;  
            end  
            DONE: begin  
                transfer_done = 1;  
                next_state = IDLE;  
            end  
            default: next_state = IDLE;  
        endcase  
    end  
endmodule

