module DAC_Controller(
    input clk,
    input reset,
    input start,
    input [23:0] digital_input,
    output reg analog_output,
    output reg done
);

reg [23:0] value;
reg [4:0] counter; // Counter for 24 cycles

always @(posedge clk or posedge reset) begin
    if (reset) begin
        value <= 24'b0;
        analog_output <= 1'b0;
        done <= 1'b0;
        counter <= 5'b0;
    end else if (start) begin
        value <= digital_input;
        counter <= 5'b0; // Reset counter
        done <= 1'b0; // Not done until conversion is complete
    end else if (counter < 24) begin
        // Simulate conversion process
        analog_output <= value[counter]; // Just for example, output the bit
        counter <= counter + 1;
    end else if (counter == 24) begin
        done <= 1'b1; // Set done signal when conversion is complete
    end
end

endmodule

