module watchdog_timer(
    input wire clk,
    input wire reset,
    output reg timeout
);
    parameter COUNT_VALUE = 10; // example count value
    reg [3:0] count; // 4-bit counter (up to 15)

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            timeout <= 0;
        end else begin
            if (count < COUNT_VALUE) begin
                count <= count + 1;
                timeout <= 0;
            end else begin
                timeout <= 1;
            end
        end
    end
endmodule

