module clock_gating (
    input wire clk,
    input wire ce,
    input wire rst,
    output reg gated_clk
);
    reg ce_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            ce_reg <= 1'b0;
            gated_clk <= 1'b0;
        end else begin
            ce_reg <= ce;
            gated_clk <= ce_reg ? clk : 1'b0;
        end
    end
endmodule

module second_order_iir_filter (
    input clk,
    input reset,
    input signed [15:0] x_in,
    output reg signed [15:0] y_out
);
    reg signed [15:0] x1, x2; // previous inputs
    reg signed [15:0] y1, y2; // previous outputs

    // Coefficients for the 2nd-order IIR filter
    parameter signed [15:0] b0 = 16'h2000; // feedforward coefficient
    parameter signed [15:0] b1 = 16'h2000; // feedforward coefficient
    parameter signed [15:0] b2 = 16'h0000; // feedforward coefficient
    parameter signed [15:0] a1 = 16'hE000; // feedback coefficient
    parameter signed [15:0] a2 = 16'h8000; // feedback coefficient

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            x1 <= 0;
            x2 <= 0;
            y1 <= 0;
            y2 <= 0;
            y_out <= 0;
        end else begin
            // Shift the values
            x2 <= x1;
            x1 <= x_in;

            y_out <= (b0 * x_in + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2) >>> 15;

            // Shift outputs
            y2 <= y1;
            y1 <= y_out;
        end
    end
endmodule

module serializer (  
    input wire clk,  
    input wire reset,  
    input wire shift_enable,  
    input wire [7:0] data_in,  
    output reg serial_out  
);  

    reg [2:0] bit_counter;  
    reg [7:0] shift_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            bit_counter <= 3'b000;  
            shift_reg <= 8'b00000000;  
            serial_out <= 1'b0;  
        end else if (shift_enable) begin  
            if (bit_counter < 3'b111) begin  
                serial_out <= shift_reg[7];  
                shift_reg <= {shift_reg[6:0], 1'b0};  
                bit_counter <= bit_counter + 1;  
            end else begin  
                serial_out <= 1'b0;  
            end  
        end else begin  
            shift_reg <= data_in;  
            bit_counter <= 3'b000;  
        end  
    end  
endmodule

