module tcp_segmenter(
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire data_valid,
    input wire [15:0] mtu, // maximum transmission unit
    output reg [7:0] packet_out,
    output reg packet_valid
);
    localparam HEADER_SIZE = 20; // in bytes
    reg [15:0] data_count;
    reg [15:0] total_bytes;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            data_count <= 0;
            total_bytes <= 0;
            packet_valid <= 0;
        end else if (data_valid) begin
            if (total_bytes < mtu) begin
                if (data_count < mtu - HEADER_SIZE) begin
                    packet_out <= data_in;
                    data_count <= data_count + 1;
                    total_bytes <= total_bytes + 1;
                    packet_valid <= 1; // indicate valid packet
                end else begin
                    packet_valid <= 0; // no more data can be added
                end
            end else begin
                data_count <= 0; // reset for new packet
                total_bytes <= 0;
                packet_valid <= 0;
            end
        end
    end
endmodule

