module rsa_encrypt (
    input [15:0] plaintext,
    input [15:0] exponent,
    output reg [15:0] ciphertext,
    input clk,
    input reset
);
    reg [15:0] result;
    reg [15:0] base;
    reg [15:0] exp;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            result <= 16'd1;
            base <= plaintext;
            exp <= exponent;
            ciphertext <= 16'd0;
        end else begin
            if (exp > 0) begin
