module SR_Latch (  
    input S,  
    input R,  
    output reg Q,  
    output reg Qn  
);  
    always @ (S or R) begin  
        if (S && !R) begin  
            Q = 1;  
            Qn = 0;  
        end else if (!S && R) begin  
            Q = 0;  
            Qn = 1;  
        end  
        // Hold state when both S and R are low  
    end  
endmodule

module uart_transmitter(
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);

    parameter BAUD_RATE = 9600;
    parameter CLOCK_RATE = 50000000; // Example clock rate
    localparam DIVISOR = CLOCK_RATE / BAUD_RATE;

    reg [3:0] state;
    reg [3:0] bit_count;
    reg [12:0] clk_count;

    localparam IDLE = 4'b0000,
               START_BIT = 4'b0001,
               DATA_BITS = 4'b0010,
               STOP_BIT = 4'b0011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1; // Idle state for TX is high
            busy <= 0;
            bit_count <= 0;
            clk_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (enable) begin
                        busy <= 1;
                        state <= START_BIT;
                        tx <= 0; // Start bit
                        bit_count <= 0;
                        clk_count <= 0;
                    end
                end
                START_BIT: begin
                    if (clk_count == DIVISOR - 1) begin
                        clk_count <= 0;
                        state <= DATA_BITS;
                    end else begin
                        clk_count <= clk_count + 1;
                    end
                end
                DATA_BITS: begin
                    if (clk_count == DIVISOR - 1) begin
                        clk_count <= 0;
                        tx <= data_in[bit_count];
                        if (bit_count == 7) begin
                            state <= STOP_BIT;
                        end else begin
                            bit_count <= bit_count + 1;
                        end
                    end else begin
                        clk_count <= clk_count + 1;
                    end
                end
                STOP_BIT: begin
                    if (clk_count == DIVISOR - 1) begin
                        clk_count <= 0;
                        tx <= 1; // Stop bit
                        busy <= 0;
                        state <= IDLE;
                    end else begin
                        clk_count <= clk_count + 1;
                    end
                end
            endcase
        end
    end
endmodule

