module LIFO_Stack (
    input wire clk,
    input wire reset,
    input wire push,
    input wire pop,
    input wire [7:0] data_in,
    output reg [7:0] data_out,
    output reg empty,
    output reg full
);
    reg [7:0] stack [7:0]; // Stack of depth 8
    reg [2:0] top; // Pointer to the top of the stack

    initial begin
        top = 0;
        empty = 1;
        full = 0;
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            top <= 0;
            empty <= 1;
            full <= 0;
        end else begin
            if (push && !full) begin
                stack[top] <= data_in;
                top <= top + 1;
            end
            if (pop && !empty) begin
                top <= top - 1;
                data_out <= stack[top];
            end

            empty <= (top == 0);
            full <= (top == 8);
        end
    end
endmodule

