module crc_generator (  
    input wire clk,  
    input wire reset,  
    input wire [3:0] data_in,  
    output reg [2:0] crc_out  
);  
    reg [3:0] shift_reg;  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 0;  
            crc_out <= 0;  
        end else begin  
            shift_reg <= data_in;  
            crc_out <= 0;  
            for (i = 0; i < 4; i = i + 1) begin  
                if (shift_reg[3] == 1) begin  
                    shift_reg = shift_reg ^ 4'b1011;  
                end  
                crc_out = {crc_out[1:0], shift_reg[3]};  
                shift_reg = {shift_reg[2:0], 1'b0};  
            end  
        end  
    end  
endmodule

module bluetooth_fsm(  
    input clk,  
    input reset,  
    input start,  
    input connected,  
    input disconnect,  
    output reg [1:0] state  
);  
    parameter IDLE = 2'b00,  
              CONNECTING = 2'b01,  
              CONNECTED = 2'b10,  
              DISCONNECTED = 2'b11;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: if (start) state <= CONNECTING;  
                CONNECTING: if (connected) state <= CONNECTED;  
                CONNECTED: if (disconnect) state <= DISCONNECTED;  
                DISCONNECTED: if (reset) state <= IDLE;  
                default: state <= IDLE;  
            endcase  
        end  
    end  
endmodule

